/**
 * Brand gradients — composed from OSMO color tokens (no raw hex, no dead ramps).
 * Violet ramp was removed with Tailwind palette; gradient now uses forest → brand
 * (deep green into Atom orange) for the AI→results story.
 *
 * ALLOWED: hero headline keywords (.text-gradient) and section backgrounds (.bg-*).
 * FORBIDDEN: buttons and CTAs (use .button--primary/--secondary), icons, chips.
 */

:root {
  --gradient-brand: linear-gradient(135deg, var(--color-forest) 0%, var(--brand) 100%);
  --gradient-brand-soft: linear-gradient(
    135deg,
    color-mix(in srgb, var(--color-green-electric) 12%, var(--background)) 0%,
    var(--background) 55%,
    var(--color-orange-50) 100%
  );
  --gradient-dark-glow:
    radial-gradient(60% 80% at 85% 20%, color-mix(in srgb, var(--color-green-electric) 18%, transparent) 0%, transparent 70%),
    radial-gradient(50% 70% at 10% 90%, color-mix(in srgb, var(--brand) 14%, transparent) 0%, transparent 70%),
    linear-gradient(135deg, var(--color-neutral-950) 0%, var(--color-neutral-900) 100%);
}

/* Keyword/headline emphasis. Brand rules: hero headlines only, max 2 highlight
   colors per title, "Atom" stays orange. */
.text-gradient {
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/**
 * Section background variants for layouts (bgStyle slot in the MCP catalog).
 * Dark variants set a light foreground so sections meet WCAG AA out of the box.
 * Never pure black (brand rule) — dark base is neutral-900/950.
 *
 * USAGE RULE: white is the page base (humanity). .bg-dark / .bg-dark-glow are
 * EXCLUSIVELY for sections about AI (agents, automation) — 0-2 per page, never
 * the whole page. These classes go on <section>, never on body or buttons.
 */

.bg-gradient-brand {
  background: var(--gradient-brand);
  color: var(--primary-foreground);
}

.bg-gradient-soft {
  background: var(--gradient-brand-soft);
}

.bg-dark {
  background-color: var(--color-neutral-900);
  color: var(--color-neutral-50);
}

.bg-dark-glow {
  background: var(--gradient-dark-glow);
  color: var(--color-neutral-50);
}

/* Soft brand wash (replaces removed violet-soft) */
.bg-brand-soft {
  background-color: var(--color-orange-50);
}

.bg-forest-soft {
  background-color: color-mix(in srgb, var(--color-forest) 8%, var(--background));
}

